. evidence/lib.sh
ev_init P-4 "Linux: users added later and Firefox profiles created later" "A user created after the import, or a Firefox profile created after it, does not get the certificate until the script runs again." "Confirm, so the guide can tell people to rerun the script." >/dev/null
ev_vm P-4 create-user "id labx >/dev/null 2>&1 && userdel -r labx 2>/dev/null; useradd -m -s /bin/bash labx; ls -a /home/labx | head -8; echo '--- stores before any import:'; bash /tmp/liststores.sh | sed -n '/user labx/,/^== user [^l]/p' | head -6" >/dev/null
ev_vm P-4 run-script "/opt/company/import-patched.sh 2>&1 | tail -3; echo '--- stores for labx after the script:'; bash /tmp/liststores.sh | sed -n '/user labx/,\$p' | head -6; ls -d /home/labx/.mozilla /home/labx/.config/mozilla /home/labx/snap/firefox 2>&1 | head -3" >/dev/null
ev_vm P-4 firefox-profile-created-later "runuser -u labx -- mkdir -p /home/labx/.mozilla/firefox/lab01.default && runuser -u labx -- certutil -N -d sql:/home/labx/.mozilla/firefox/lab01.default --empty-password; echo '--- a Firefox profile now exists (simulated: empty NSS database), before rerun:'; bash /tmp/liststores.sh | sed -n '/user labx/,\$p' | head -6; echo; /opt/company/import-patched.sh >/dev/null 2>&1; echo '--- after rerunning the script:'; bash /tmp/liststores.sh | sed -n '/user labx/,\$p' | head -6" >/dev/null
ev_vm P-4 cleanup "userdel -r labx 2>&1; id labx 2>&1 | head -1" >/dev/null
